# Generated for J-1041, target: master
Configuration PE_J1041 {
    Import-DscResource -ModuleName Microsoft365DSC -ModuleVersion 2.26.1015.1
    Node localhost {
        EXOTransportRule 'Block executable attachments' {
            Name                             = 'Block executable attachments'
            Enabled                          = $true
            Mode                             = 'Enforce'
            FromScope                        = 'NotInOrganization'
            ApplyHtmlDisclaimerLocation      = 'Prepend'
            ApplyHtmlDisclaimerText          = '[External] Take care with links.'
            StopRuleProcessing               = $false
            Ensure                           = 'Present'
            ApplicationId                    = $ConfigurationData.NonNodeData.ApplicationId
            TenantId                         = $ConfigurationData.NonNodeData.TenantId
            CertificateThumbprint            = $ConfigurationData.NonNodeData.CertificateThumbprint
        }
    }
}
